const uri = process.env.MONGODB_URI;
const dbName = process.env.DB_NAME || 'clientify_vault';

export const client = new MongoClient(uri, {
  serverApi: {
    version: ServerApiVersion.v1,
    strict: true,
    deprecationErrors: true,
  }
});

export async function connectDB() {
  try {
    await client.connect();
    const db = client.db(dbName);
    // Create unique indexes for auth
    await db.collection('users').createIndex({ user_id: 1 }, { unique: true });
    await db.collection('users').createIndex({ email_id: 1 }, { unique: true });
    // Index for fast item lookup by user
    await db.collection('items').createIndex({ createdBy: 1, name: 1 });
    console.log("🛡️ Vault connected to MongoDB Atlas");
    return db;
  } catch (error) {
    console.error('❌ DB Connection Failed:', error);
    process.exit(1);
  }
}

export const getCollection = (name) => client.db(dbName).collection(name);

import express from 'express';
import cors from 'cors';
import authRoutes from './auth/auth.routes.js';
import itemRoutes from './routes/items.routes.js';

export const app = express();

// CORS configuration is critical to prevent "unexpected response"
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', 
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

app.use(express.json());

// API Routes
app.use('/api/auth', authRoutes);
app.use('/api/items', itemRoutes);

// Health check for Render
app.get('/api/health', (req, res) => res.json({ status: 'live' }));

// Global Error Handler returns JSON (prevents HTML error pages)
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Vault Internal Error', message: err.message });
});

import { API_BASE_URL } from '../constants.ts';

class ApiService {
  private token: string | null = null;

  setToken(token: string | null) {
    this.token = token;
  }

  private getFullUrl(endpoint: string): string {
    const path = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    const apiPath = path.startsWith('/api') ? path : `/api${path}`;
    // Fallback logic for local vs production
    const base = API_BASE_URL || window.location.origin;
    return `${base}${apiPath}`;
  }

  private async handleResponse(response: Response) {
    const contentType = response.headers.get("content-type");
    if (!contentType || !contentType.includes("application/json")) {
      const text = await response.text();
      throw new Error(`Server returned non-JSON response. Check VITE_BACKEND_URL setting. Status: ${response.status}`);
    }

    const result = await response.json();
    if (!response.ok) throw new Error(result.message || result.error || 'Vault Access Denied');
    return result;
  }

  async get(endpoint: string) {
    const headers = this.token ? { 'Authorization': `Bearer ${this.token}` } : {};
    const res = await fetch(this.getFullUrl(endpoint), { method: 'GET', headers });
    return this.handleResponse(res);
  }

  async post(endpoint: string, data: any) {
    const headers = {
      'Content-Type': 'application/json',
      ...(this.token ? { 'Authorization': `Bearer ${this.token}` } : {})
    };
    const res = await fetch(this.getFullUrl(endpoint), {
      method: 'POST',
      headers,
      body: JSON.stringify(data),
    });
    return this.handleResponse(res);
  }

  async put(endpoint: string, data: any) {
    const headers = {
      'Content-Type': 'application/json',
      ...(this.token ? { 'Authorization': `Bearer ${this.token}` } : {})
    };
    const res = await fetch(this.getFullUrl(endpoint), {
      method: 'PUT',
      headers,
      body: JSON.stringify(data),
    });
    return this.handleResponse(res);
  }

  async delete(endpoint: string) {
    const headers = this.token ? { 'Authorization': `Bearer ${this.token}` } : {};
    const res = await fetch(this.getFullUrl(endpoint), { method: 'DELETE', headers });
    return this.handleResponse(res);
  }
}

