import jwt from 'jsonwebtoken';
import { ObjectId } from 'mongodb';
import { getCollection } from '../db/mongo.js';

export const authenticate = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: No token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const user = await getCollection('users').findOne({ _id: new ObjectId(decoded.id) });

    if (!user) return res.status(401).json({ error: 'Practitioner not found' });

    req.user = user;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid or expired vault session' });
  }
};

import { getCollection } from '../db/mongo.js';
import { ObjectId } from 'mongodb';

export const getItems = async (req, res) => {
  try {
    const items = await getCollection('items')
      .find({ createdBy: req.user._id }) // CRITICAL: Strict ownership
      .sort({ updatedAt: -1 })
      .toArray();
    res.json(items);
  } catch (err) {
    res.status(500).json({ error: 'Failed to retrieve vault records' });
  }
};

export const createItem = async (req, res) => {
  try {
    const newItem = {
      ...req.body,
      createdBy: req.user._id, // Auto-attach owner
      createdAt: new Date(),
      updatedAt: new Date()
    };
    const result = await getCollection('items').insertOne(newItem);
    res.status(201).json({ ...newItem, _id: result.insertedId });
  } catch (err) {
    res.status(500).json({ error: 'Failed to archive record' });
  }
};

export const updateItem = async (req, res) => {
  try {
    const { id } = req.params;
    const result = await getCollection('items').findOneAndUpdate(
      { _id: new ObjectId(id), createdBy: req.user._id },
      { $set: { ...req.body, updatedAt: new Date() } },
      { returnDocument: 'after' }
    );
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
};

