import { useState, useEffect, useCallback } from 'react';
import { api } from '../services/api.ts';
import { socketService } from '../services/socket.ts';
import { 
  Client, 
  LitigationRecord, 
  MiscWorkRecord, 
  PaymentRecord, 
  GSTRegistrationRecord, 
  FoodLicenseRecord, 
  MSMERegistrationRecord, 
  InvoiceRecord 
} from '../types.ts';

export const useClientData = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [litigationRecords, setLitigationRecords] = useState<LitigationRecord[]>([]);
  const [miscellaneousWork, setMiscellaneousWork] = useState<MiscWorkRecord[]>([]);
  const [payments, setPayments] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const fetchData = useCallback(async () => {
    setIsSyncing(true);
    try {
      const summary = await api.getDashboardSummary();
      setClients(summary.clients || []);
      setInvoices(summary.invoices || []);
      setLitigationRecords(summary.litigation || []);
      setMiscellaneousWork(summary.work || []);

      const [pays] = await Promise.all([
        api.getPayments()
      ]);
      setPayments(pays || []);
    } catch (err) {
      console.error("Vault Sync Failure:", err);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
    socketService.connect();
    socketService.on('db_item_change', fetchData);
    return () => {
      socketService.disconnect();
    };
  }, [fetchData]);

  const updateClient = async (client: Partial<Client>) => {
    await api.saveClient(client);
    fetchData();
  };

  return {
    clients,
    invoices,
    litigationRecords,
    miscellaneousWork,
    payments,
    isLoading,
    isSyncing,
    fetchData,
    updateClient,
    gstNotices: litigationRecords.filter(r => r.category === 'Notice'),
    gstAppeals: litigationRecords.filter(r => r.category === 'Appeal'),
    gstTribunalAppeals: litigationRecords.filter(r => r.category === 'Tribunal'),
    highCourtAppeals: litigationRecords.filter(r => r.category === 'HighCourt'),
    gstRegistrations: [], // To be fetched from specific endpoints if needed
    foodLicenses: [],
    msmeRegistrations: [],
    reminders: []
  };
};

import { useCallback } from 'react';

export const useDueDate = () => {
  const STORAGE_KEY = 'clientify_global_compliance_dates_v1';

  const getDueDate = useCallback((module: string, fy: string, period?: string) => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (!saved) return '';

    try {
      const dates = JSON.parse(saved);
      const keyMap: Record<string, string> = {
        'Audit': `audit_tax_${fy}_Annual`,
        'BalanceSheet': `audit_bs_${fy}_Annual`,
        'ITR': `itr_return_${fy}_Annual`,
        'GSTR-1 Monthly': `monthly_r1_${fy}_${period}`,
        'GSTR-3B Monthly': `monthly_r3b_${fy}_${period}`,
        'GSTR-1 Quarterly': `quarterly_iff_${fy}_${period}`,
        'GSTR-3B Quarterly': `quarterly_r3b_${fy}_${period}`,
        'CMP-08': `composition_cmp08_${fy}_${period}`,
        'GSTR-4': `annual_gstr4_${fy}_Annual`,
        'GSTR-9': `annual_gstr9_${fy}_Annual`,
        'GSTR-9C': `annual_gstr9c_${fy}_Annual`
      };

      const key = keyMap[module] || `${module}_${fy}_${period}`;
      return dates[key] || '';
    } catch {
      return '';
    }
  }, []);

  return { getDueDate };
};

