import React, { useState, useEffect, useCallback } from 'react';
import { AuthProvider, useAuth } from './auth/AuthContext.tsx';
import ProtectedRoute from './components/ProtectedRoute.tsx';
import Navbar from './components/Navbar.tsx';
import Home from './pages/Home.tsx';
import Dashboard from './pages/Primary/Dashboard.tsx';
import Login from './auth/Login.tsx';
import Signup from './auth/Signup.tsx';
import Loader from './components/Loader.tsx';
import OfflineBanner from './components/OfflineBanner.tsx';
import { api } from './services/api.ts';
import { useOffline } from './hooks/useOffline.ts';
// Imported View enum from types to handle navigation state
import { View } from './types.ts';

type Page = 'home' | 'login' | 'signup' | 'dashboard';

const AppContent: React.FC = () => {
  const { isAuthenticated, token, hasCheckedAuth, isLoading } = useAuth();
  const [currentPage, setCurrentPage] = useState<Page>('home');
  // Added local state to track active dashboard module view
  const [activeView, setActiveView] = useState<View>(View.Dashboard);

  const handleReconnect = useCallback(() => {
    if (token) api.get('/auth/me').catch(() => {});
  }, [token]);

  const isOnline = useOffline(handleReconnect);

  useEffect(() => {
    if (!hasCheckedAuth) return;
    if (isAuthenticated) {
      setCurrentPage('dashboard');
    } else {
      if (currentPage === 'dashboard') setCurrentPage('home');
    }
  }, [isAuthenticated, hasCheckedAuth, currentPage]);

  if (!hasCheckedAuth) return <Loader />;

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return (
          <>
            <Navbar onLoginClick={() => setCurrentPage('login')} onHomeClick={() => setCurrentPage('home')} />
            <Home onGetStarted={() => setCurrentPage('signup')} />
          </>
        );
      case 'login':
        return <Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />;
      case 'signup':
        return <Signup onSwitch={() => setCurrentPage('login')} onBackToHome={() => setCurrentPage('home')} />;
      case 'dashboard':
        return (
          <ProtectedRoute fallback={<Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />}>
            {/* Provided required setActiveView prop to fix component initialization error */}
            <Dashboard setActiveView={setActiveView} />
          </ProtectedRoute>
        );
      default:
        return <Home onGetStarted={() => setCurrentPage('signup')} />;
    }
  };

  return (
    <>
      <OfflineBanner isOnline={isOnline} />
      {renderPage()}
      {isLoading && <div className="fixed inset-0 z-[9999] bg-slate-950/20 backdrop-blur-sm"><Loader /></div>}
    </>
  );
};

const App: React.FC = () => (
  <AuthProvider>
    <AppContent />
  </AuthProvider>
);

export default App;

import { useState, useEffect, useCallback } from 'react';
import { api } from '../services/api.ts';
import { socketService } from '../services/socket.ts';
import { 
  Client, 
  LitigationRecord, 
  MiscWorkRecord, 
  PaymentRecord, 
  GSTRegistrationRecord, 
  FoodLicenseRecord, 
  MSMERegistrationRecord, 
  InvoiceRecord 
} from '../types.ts';

export const useClientData = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [litigationRecords, setLitigationRecords] = useState<LitigationRecord[]>([]);
  const [miscellaneousWork, setMiscellaneousWork] = useState<MiscWorkRecord[]>([]);
  const [payments, setPayments] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const fetchData = useCallback(async () => {
    setIsSyncing(true);
    try {
      const summary = await api.getDashboardSummary();
      setClients(summary.clients || []);
      setInvoices(summary.invoices || []);
      setLitigationRecords(summary.litigation || []);
      setMiscellaneousWork(summary.work || []);

      const [pays] = await Promise.all([
        api.getPayments()
      ]);
      setPayments(pays || []);
    } catch (err) {
      console.error("Vault Sync Failure:", err);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
    socketService.connect();
    socketService.on('db_item_change', fetchData);
    return () => {
      socketService.disconnect();
    };
  }, [fetchData]);

  const updateClient = async (client: Partial<Client>) => {
    await api.saveClient(client);
    fetchData();
  };

  return {
    clients,
    invoices,
    litigationRecords,
    miscellaneousWork,
    payments,
    isLoading,
    isSyncing,
    fetchData,
    updateClient,
    gstNotices: litigationRecords.filter(r => r.category === 'Notice'),
    gstAppeals: litigationRecords.filter(r => r.category === 'Appeal'),
    gstTribunalAppeals: litigationRecords.filter(r => r.category === 'Tribunal'),
    highCourtAppeals: litigationRecords.filter(r => r.category === 'HighCourt'),
    gstRegistrations: [], 
    foodLicenses: [],
    msmeRegistrations: [],
    reminders: []
  };
};

