import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Client, ClientStatus, GstnStatus } from '../types';
import { useClientData } from '../hooks/useClientData';
import { ClientFormModal } from './ClientFormModal';
import { FullDetailsModal } from './FullDetailsModal';
import { PasswordEditModal } from './PasswordEditModal';
import { ImportClientsModal } from './ImportClientsModal';
import { PlusIcon, PencilIcon, ShareIcon, EyeIcon, CertificateIcon, ImportIcon, FilterIcon, SearchIcon, TrashIcon } from './icons';

// Helper functions to extract data safely
const getBusinessName = (client: Client) => client.gstDetails?.tradeName || `Client`;
const getPrimaryMember = (client: Client) => client.gstDetails?.members?.[0] || { name: '-', mobile: '-' };
const getPan = (client: Client) => client.gstDetails?.gstin?.substring(2, 12) || '-';

type PasswordField = { client: Client; fieldPath: string; label: string; }
type ToastMessage = { type: 'success' | 'error'; message: string; }

function dataURLtoFile(dataurl: string, filename: string): File | null {
    const arr = dataurl.split(',');
    if (arr.length < 2) return null;
    const mimeMatch = arr[0].match(/:(.*?);/);
    if (!mimeMatch) return null;
    const mime = mimeMatch[1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
    }
    return new File([u8arr], filename, { type: mime });
}

const GstClientDetails: React.FC = () => {
    const { clients, addClient, addMultipleClients, updateClient, deleteClient } = useClientData();
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState<'all' | ClientStatus>('all');
    const [gstStatusFilter, setGstStatusFilter] = useState<'all' | GstnStatus>('all');

    // Modal states
    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);

    // Filter popover state
    const [openFilter, setOpenFilter] = useState<string | null>(null);
    const filterRef = useRef<HTMLDivElement>(null);

    // Data for modals
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [viewingClient, setViewingClient] = useState<{client: Client, sno: number} | null>(null);
    const [editingPasswordField, setEditingPasswordField] = useState<PasswordField | null>(null);
    const [toastMessage, setToastMessage] = useState<ToastMessage | null>(null);

    const getClientStatusColor = (status: ClientStatus) => {
        switch (status) {
            case ClientStatus.ACTIVE_FILING: return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
            case ClientStatus.CASE_BY_CASE: return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300';
            case ClientStatus.INACTIVE_TEMPORARY: return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300';
            case ClientStatus.INACTIVE_CLOSED: return 'bg-gray-200 text-gray-800 dark:bg-gray-600 dark:text-gray-300';
            case ClientStatus.MANAGED_BY_OTHERS: return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300';
            default: return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300';
        }
    };

    useEffect(() => {
        if (toastMessage) {
            const timer = setTimeout(() => setToastMessage(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toastMessage]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (filterRef.current && !filterRef.current.contains(event.target as Node)) {
                 const targetEl = event.target as Element;
                if (targetEl.closest('th button')) {
                    return;
                }
                setOpenFilter(null);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [filterRef]);

    const handleAddNew = () => {
        setEditingClient(null);
        setIsFormModalOpen(true);
    };

    const handleEdit = (client: Client) => {
        setEditingClient(client);
        setIsFormModalOpen(true);
    };

    const handleEditFromDetails = (client: Client) => {
        setIsDetailsModalOpen(false);
        handleEdit(client);
    };

    const handleViewDetails = (client: Client, sno: number) => {
        setViewingClient({ client, sno });
        setIsDetailsModalOpen(true);
    };

    const handleOpenPasswordModal = (client: Client, fieldPath: string, label: string) => {
        setEditingPasswordField({ client, fieldPath, label });
        setIsPasswordModalOpen(true);
    };

    const handleSaveClient = (client: Client) => {
        if ('id' in client && client.id) {
            updateClient(client);
            setToastMessage({ type: 'success', message: 'Client updated successfully!' });
        } else {
            addClient(client);
            setToastMessage({ type: 'success', message: 'Client added successfully!' });
        }
    };

    const handleDeleteClient = (clientId: string, e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation(); // Prevent event bubbling
        const clientToDelete = clients.find(c => c.id === clientId);
        if (!clientToDelete) return;

        const clientName = getBusinessName(clientToDelete);
        if (window.confirm(`Are you sure you want to delete ${clientName}? This action cannot be undone.`)) {
            // Wrap in setTimeout to ensure confirm dialog clears and state update is processed in next tick
            setTimeout(() => {
                deleteClient(clientId);
                setToastMessage({ type: 'success', message: 'Client deleted successfully.' });
            }, 0);
        }
    };

    const handleImport = (newClients: Omit<Client, 'id'>[]) => {
        const existingGstins = new Set(clients.map(c => c.gstDetails?.gstin?.toUpperCase()).filter(Boolean));
        const clientsToAdd = newClients.filter(nc => {
            const gstin = nc.gstDetails?.gstin?.toUpperCase();
            return gstin && !existingGstins.has(gstin);
        });
        const skippedCount = newClients.length - clientsToAdd.length;
        if (clientsToAdd.length > 0) {
            addMultipleClients(clientsToAdd);
        }
        setIsImportModalOpen(false);
        let message = '';
        if (clientsToAdd.length > 0) {
            message += `${clientsToAdd.length} client(s) imported successfully. `;
        }
        if (skippedCount > 0) {
            message += `${skippedCount} duplicate client(s) were skipped.`;
        }
        if (!message) {
            message = 'No new clients to import.';
        }
        setToastMessage({ type: 'success', message: message.trim() });
    };

    const handleShare = async (client: Client) => {
        const credentials = [
            `*GST Credentials for: ${getBusinessName(client)}*`,
            `---------------------------------`,
            `*GSTIN:* ${client.gstDetails?.gstin || 'N/A'}`,
            `*GST ID:* ${client.gstDetails?.gstId || 'N/A'}`,
            `*GST Pwd:* ${client.gstDetails?.gstPassword || 'N/A'}`,
        ].join('\n');
        const shareData = { title: `GST Credentials: ${getBusinessName(client)}`, text: credentials };
        if (navigator.share) {
            try { await navigator.share(shareData); } catch (err) { console.error('Error sharing:', err); if ((err as DOMException).name !== 'AbortError') setToastMessage({ type: 'error', message: 'Could not share credentials.' }); }
        } else {
            try { await navigator.clipboard.writeText(credentials); setToastMessage({ type: 'success', message: 'Credentials copied to clipboard!' }); } catch (err) { console.error('Failed to copy:', err); setToastMessage({ type: 'error', message: 'Failed to copy credentials.' }); }
        }
    };

    const handleShareCertificate = async (client: Client) => {
        const cert = client.gstDetails?.gstCertificate;
        if (cert && cert.dataUrl) {
            const file = dataURLtoFile(cert.dataUrl, cert.name);
            if (!file) { setToastMessage({ type: 'error', message: 'Could not reconstruct certificate file.' }); return; }
            if (navigator.canShare && navigator.canShare({ files: [file] })) {
                try { await navigator.share({ files: [file], title: `GST Certificate: ${getBusinessName(client)}`, text: `Here is the GST certificate for ${getBusinessName(client)}.` }); } catch (err) { console.error('Error sharing file:', err); if ((err as DOMException).name !== 'AbortError') setToastMessage({ type: 'error', message: 'Could not share certificate.' }); }
            } else { setToastMessage({ type: 'error', message: 'File sharing is not supported on your browser.' }); }
        } else { setToastMessage({ type: 'error', message: 'No GST certificate on file for this client.' }); }
    };

    const handleSearchTaxpayer = (gstin: string | undefined) => {
        if (!gstin) { setToastMessage({ type: 'error', message: 'GSTIN not available.' }); return; }
        navigator.clipboard.writeText(gstin).then(() => { setToastMessage({ type: 'success', message: 'GSTIN copied! Opening search portal...' }); window.open(`https://services.gst.gov.in/services/searchtp`, '_blank', 'noopener,noreferrer'); }).catch(() => setToastMessage({ type: 'error', message: 'Failed to copy GSTIN.' }));
    };

    const filteredClients = useMemo(() => {
        let clientsToFilter = clients.filter(c => c.gstDetails);
        if (statusFilter !== 'all') clientsToFilter = clientsToFilter.filter(c => c.clientStatus === statusFilter);
        if (gstStatusFilter !== 'all') clientsToFilter = clientsToFilter.filter(c => c.gstDetails?.status === gstStatusFilter);
        if (!searchTerm) return clientsToFilter;
        const lowercasedFilter = searchTerm.toLowerCase();
        return clientsToFilter.filter(client => (
            client.gstDetails?.tradeName.toLowerCase().includes(lowercasedFilter) ||
            (client.gstDetails?.legalName || '').toLowerCase().includes(lowercasedFilter) ||
            client.gstDetails?.gstin.toLowerCase().includes(lowercasedFilter) ||
            getPan(client).toLowerCase().includes(lowercasedFilter)
        ));
    }, [clients, searchTerm, statusFilter, gstStatusFilter]);

    const renderTable = () => {
        return (
             <div className="bg-white dark:bg-gray-800 p-4 sm:p-6 rounded-2xl shadow-lg overflow-x-auto">
                <table className="w-full text-lg text-left text-gray-500 dark:text-gray-400">
                    <thead className="text-xs text-gray-700 uppercase bg-gray-50 dark:bg-gray-700 dark:text-gray-400">
                        <tr>
                            <th scope="col" className="px-6 py-3">S. No.</th>
                            <th scope="col" className="px-6 py-3">Trade Name</th>
                            <th scope="col" className="px-6 py-3">Legal Name</th>
                            <th scope="col" className="px-6 py-3">Mobile No.</th>
                            <th scope="col" className="px-6 py-3">GSTIN</th>
                            <th scope="col" className="px-6 py-3">
                                <div className="flex items-center relative">
                                    GST Status
                                    <button onClick={() => setOpenFilter(openFilter === 'gstStatus' ? null : 'gstStatus')} className="ml-1 p-1 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700"><FilterIcon /></button>
                                    {openFilter === 'gstStatus' && (
                                        <div ref={filterRef} className="absolute top-full mt-2 z-10 w-32 bg-white dark:bg-gray-800 rounded-md shadow-lg border dark:border-gray-600">
