        ]
    },
];

const NavSelectionModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    content: { title: string; items: NavItem[] } | null;
    onSelect: (view: View) => void;
    onLogout: () => void;
}> = ({ isOpen, onClose, content, onSelect, onLogout }) => {
    if (!isOpen || !content) return null;

    const renderModalItems = (items: NavItem[]): React.ReactElement[] => {
        return items.map(item => {
            if (item.view) {
                return (
                    <li
                        key={item.id}
                        onClick={() => onSelect(item.view!)}
                        className="p-3 rounded-lg cursor-pointer transition-colors text-gray-800 dark:text-gray-200 hover:bg-indigo-100 dark:hover:bg-gray-700 flex items-center gap-3"
                    >
                        <span className="text-2xl w-6 h-6 flex items-center justify-center">{item.icon}</span>
                        <span>{item.label}</span>
                    </li>
                );
            }
            if (item.id === 'logout') {
                return (
                    <li
                        key={item.id}
                        onClick={onLogout}
                        className="p-3 rounded-lg cursor-pointer transition-colors text-red-600 dark:text-red-400 hover:bg-red-100 dark:hover:bg-gray-700 flex items-center gap-3"
                    >
                         <span className="text-2xl w-6 h-6 flex items-center justify-center">{item.icon}</span>
                        <span>{item.label}</span>
                    </li>
                );
            }
            if (item.subItems) {
                return (
                    <li key={item.id} className="mt-2">
                        <h3 className="px-3 py-1 text-sm font-semibold text-gray-500 dark:text-gray-400">{item.label}</h3>
                        <ul className="pl-4">
                            {renderModalItems(item.subItems)}
                        </ul>
                    </li>
                );
            }
            return <React.Fragment key={item.id}></React.Fragment>;
        });
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50" onClick={onClose}>
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-sm" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center p-4 border-b dark:border-gray-700">
                    <h2 className="text-xl font-bold text-gray-900 dark:text-white">Go to...</h2>
                    <button onClick={onClose} className="p-1 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700"><XIcon /></button>
                </div>
                <div className="p-4 max-h-[60vh] overflow-y-auto">
                    <h3 className="text-md font-semibold text-gray-800 dark:text-gray-200 mb-2">{content.title}</h3>
                    <ul className="space-y-1">
                       {renderModalItems(content.items)}
                    </ul>
                </div>
            </div>
        </div>
    );
};


const Sidebar: React.FC<SidebarProps> = ({ currentUser, activeView, setActiveView, onLogout, isCollapsed, toggleSidebar }) => {
    const { drive, storageMode, localDirectoryHandle, localFolderName, hasLocalPermission, requestLocalPermission } = useClientData();
    const [openSections, setOpenSections] = useState<Record<string, boolean>>({});
    const [isNavModalOpen, setIsNavModalOpen] = useState(false);
    const [modalContent, setModalContent] = useState<{ title: string; items: NavItem[] } | null>(null);

    useEffect(() => {
        const findPath = (nodes: NavItem[], targetView: View): string[] => {
            for (const node of nodes) {
                if (node.view === targetView) return [node.id];
                if (node.subItems) {
                    const path = findPath(node.subItems, targetView);
                    if (path.length > 0) return [node.id, ...path];
                }
            }
            return [];
        };
        const activePath = findPath(navStructure, activeView);
        setOpenSections(prev => {
            const newSections = { ...prev };
            activePath.forEach(id => newSections[id] = true);
            return newSections;
        });
    }, [activeView]);

    const handleToggle = (id: string) => {
        setOpenSections(prev => ({ ...prev, [id]: !prev[id] }));
    };

    const NavItem: React.FC<{ item: NavItem, level: number }> = ({ item, level }) => {
        const hasSubItems = item.subItems && item.subItems.length > 0;
        const isOpen = openSections[item.id] || false;
        const isActive = activeView === item.view;
        const isChildNodeActive = (nodes: NavItem[]): boolean => {
            return nodes.some(node => {
                if (node.view === activeView) return true;
                if (node.subItems) return isChildNodeActive(node.subItems);
                return false;
            });
        };
        const isChildActive = hasSubItems && isChildNodeActive(item.subItems!);

        const handleClick = () => {
            if (hasSubItems) {
                if (isCollapsed && window.innerWidth >= 1024) {
                    setModalContent({ title: item.label, items: item.subItems! });
                    setIsNavModalOpen(true);
                } else {
                    handleToggle(item.id);
                }
            } else if (item.view) {
                setActiveView(item.view);
                if (window.innerWidth < 1024) {
                    toggleSidebar();
                }
            } else if (item.id === 'logout') {
                onLogout();
            }
        };

        const itemStyle = { paddingLeft: `${12 + level * 16}px` };
        const iconStyle = { width: '1.5rem', height: '1.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: level > 0 ? '1rem' : '1.5rem' };

        return (
            <>
                <li
                    onClick={handleClick}
                    className={`flex items-center justify-between p-3 my-1 rounded-lg cursor-pointer transition-colors ${
                        isActive
                            ? 'bg-indigo-600 text-white shadow-lg'
                            : isChildActive 
                            ? 'text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-gray-700'
                            : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
                    }`}
                    style={itemStyle}
                >
                    <div className="flex items-center overflow-hidden">
                        <span style={iconStyle} className="flex-shrink-0">{item.icon}</span>
                        <span className={`ml-4 font-medium transition-opacity duration-300 truncate ${isCollapsed ? 'lg:opacity-0 lg:hidden' : 'opacity-100'}`}>
                           {item.label}
                        </span>
                    </div>
                    {hasSubItems && !isCollapsed && (
                        <span className={`transition-transform transform ml-auto flex-shrink-0 ${isOpen ? 'rotate-180' : ''}`}>
                            <ChevronDownIcon />
                        </span>
                    )}
                </li>
                {hasSubItems && isOpen && !isCollapsed && (
                    <ul className="transition-all duration-300 ease-in-out">
