    const gstr9cFiled = filteredClients.filter(c => getStatus(c.id).gstr9c).length;
    return { total, gstr9Filed, gstr9cFiled };
  }, [filteredClients, getStatus]);

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-8 animate-in fade-in duration-500 overflow-hidden">

      {/* Summary Cards */}
