        setTimeout(() => syncEntityDetails(prev.gstProfile!.constitution, updatedStakeholders[0]), 0);
      }
      return {
        ...prev,
        gstProfile: {
          ...prev.gstProfile!,
          stakeholders: updatedStakeholders
        }
      };
    });
