    };
    return map[activeView] || { label: activeView.toUpperCase().replace(/-/g, ' '), desc: 'Authorized Vault Module' };
  };

  const headerInfo = getHeaderInfo();

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900 overflow-hidden">
