          activeViewDescription={headerInfo.desc}
          onViewChange={setActiveView}
        />

        <div className="flex-1 overflow-y-auto no-scrollbar p-6 bg-slate-50">
          <div className="max-w-[1600px] mx-auto h-full">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

