const Sidebar: React.FC<SidebarProps> = ({ activeView, onViewChange, isCollapsed, onToggle }) => {
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const findPath = (items: NavItem[], targetView: ActiveView): string[] => {
        for (const item of items) {
            if (item.view === targetView) return [item.id];
            if (item.subItems) {
                const sub = findPath(item.subItems, targetView);
                if (sub.length > 0) return [item.id, ...sub];
            }
        }
        return [];
    };
    const path = findPath(navStructure, activeView);
    if (path.length > 0) {
        setOpenSections(prev => {
            const next = { ...prev };
            path.forEach(id => next[id] = true);
            return next;
        });
    }
  }, [activeView]);

  const toggleSection = (id: string) => {
    setOpenSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const NavItemComponent: React.FC<{ item: NavItem; level: number }> = ({ item, level }) => {
    const hasSubItems = !!item.subItems?.length;
    const isOpen = openSections[item.id];
    const isActive = activeView === item.view;

    const isChildActive = (nodes: NavItem[]): boolean => {
        return nodes.some(node => node.view === activeView || (node.subItems && isChildActive(node.subItems)));
    };
    const childActive = hasSubItems && isChildActive(item.subItems!);

    const handleClick = () => {
      if (hasSubItems) {
        toggleSection(item.id);
      } else if (item.view) {
        onViewChange(item.view);
      }
    };

    return (
      <div className="w-full">
        <button
          onClick={handleClick}
          style={{ paddingLeft: isCollapsed ? '0' : `${16 + level * 12}px` }}
          className={`flex w-full items-center gap-3 rounded-xl transition-all duration-300 ${
            isCollapsed ? 'justify-center py-4' : 'px-4 py-3'
          } ${
            isActive ? 'bg-indigo-600 text-white shadow-lg' : childActive ? 'bg-indigo-50 text-indigo-700' : 'text-slate-600 hover:bg-slate-100'
          }`}
        >
          <span className={`${isCollapsed ? 'text-2xl' : 'text-xl'} shrink-0`}>{item.icon}</span>
          {!isCollapsed && (
            <>
              <span className="flex-1 text-left truncate font-black text-[11px] uppercase tracking-wider">{item.label}</span>
              {hasSubItems && (
                <svg className={`h-3 w-3 transition-transform ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
                </svg>
              )}
            </>
          )}
        </button>

        {hasSubItems && isOpen && !isCollapsed && (
          <div className="mt-1 space-y-1">
            {item.subItems?.map(sub => <NavItemComponent key={sub.id} item={sub} level={level + 1} />)}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside className={`fixed inset-y-0 left-0 z-[70] flex flex-col border-r border-slate-200 bg-white shadow-2xl transition-all duration-500 ${isCollapsed ? 'w-20' : 'w-80'}`}>
      <div className={`flex h-20 items-center border-b border-slate-100 px-6 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
         {!isCollapsed && (
           <div className="flex items-center gap-3">
             <div className="h-10 w-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <span className="text-xl font-black tracking-tighter text-slate-900 uppercase">Vault<span className="text-indigo-600">Core</span></span>
           </div>
         )}
         {isCollapsed && (
           <div className="h-10 w-10 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600 border border-indigo-100 shadow-sm">
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
           </div>
         )}
      </div>

      <nav className="flex-1 overflow-y-auto no-scrollbar p-4 space-y-1">
        {navStructure.map(item => <NavItemComponent key={item.id} item={item} level={0} />)}
      </nav>

      <div className="p-4 border-t border-slate-100 shrink-0">
         <button onClick={onToggle} className="w-full flex items-center justify-center h-12 rounded-2xl bg-slate-50 text-slate-400 hover:text-indigo-600 transition-all border border-slate-100">
           <svg className={`h-5 w-5 transition-transform duration-500 ${isCollapsed ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 19l-7-7m0 0l7-7m-7 7h16" /></svg>
           {!isCollapsed && <span className="text-[10px] font-black uppercase tracking-widest ml-3">Minimize Sidebar</span>}
         </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { 
  Client, 
  ConstitutionType, 
  GstRegType, 
  GstFilingFreq, 
  ClientStatus, 
  Stakeholder,
  GstStatus
} from '../../types.ts';
import { api } from '../../services/api.ts';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);

  const defaultStakeholder = (): Stakeholder => ({
    id: Math.random().toString(36).substr(2, 9),
    name: '',
    mobile: '',
    pan: '',
    itPassword: '',
    address: ''
  });

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    email: '',
    mobile: '',
    status: 'Active',
    gstProfile: {
      gstin: '',
      pan: '',
      username: '',
      password: '',
      ewayBillUsername: '',
      ewayBillPassword: '',
      gstatUsername: '',
      gstatPassword: '',
      gstStatus: 'Active',
      regDate: '',
      cancelDate: '',
      regType: 'Regular',
      filingFreq: 'Monthly',
      constitution: 'Proprietorship',
      stakeholders: [defaultStakeholder()],
      accountantName: '',
      accountantMobile: '',
      address: '',
      jurisdictionType: 'State'
    },
    bankDetails: { bankName: '', accountNo: '', ifsc: '' },
    remarks: ''
  });

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setFormData({
          ...initialData,
          gstProfile: {
            ...initialData.gstProfile!,
            stakeholders: initialData.gstProfile?.stakeholders || [defaultStakeholder()]
          }
        });
      } else {
        resetForm();
      }
    }
  }, [isOpen, initialData]);

  const resetForm = () => {
    setFormData({
      legalName: '',
      tradeName: '',
      email: '',
      mobile: '',
      status: 'Active',
      gstProfile: {
        gstin: '',
        pan: '',
        username: '',
        password: '',
        ewayBillUsername: '',
        ewayBillPassword: '',
        gstatUsername: '',
        gstatPassword: '',
        gstStatus: 'Active',
        regDate: '',
        cancelDate: '',
        regType: 'Regular',
        filingFreq: 'Monthly',
        constitution: 'Proprietorship',
        stakeholders: [defaultStakeholder()],
        accountantName: '',
        accountantMobile: '',
        address: '',
        jurisdictionType: 'State'
      },
      bankDetails: { bankName: '', accountNo: '', ifsc: '' },
      remarks: ''
    });
    setError(null);
  };

  const handleGstinChange = (val: string) => {
    const gstin = val.toUpperCase().trim().slice(0, 15);
    let pan = formData.gstProfile?.pan || '';
    if (gstin.length >= 12) pan = gstin.substring(2, 12);

    setFormData(prev => {
      const nextGst = { ...prev.gstProfile!, gstin, pan };
      if (nextGst.constitution === 'Proprietorship' && nextGst.stakeholders.length > 0) {
        nextGst.stakeholders[0] = { ...nextGst.stakeholders[0], pan };
      }
      return { ...prev, gstProfile: nextGst };
    });
  };

  const handleEntityPanChange = (val: string) => {
    const pan = val.toUpperCase().slice(0, 10);
    setFormData(prev => {
      const nextGst = { ...prev.gstProfile!, pan };
      if (nextGst.constitution === 'Proprietorship' && nextGst.stakeholders.length > 0) {
        nextGst.stakeholders[0] = { ...nextGst.stakeholders[0], pan };
      }
      return { ...prev, gstProfile: nextGst };
    });
  };

  const handleRegTypeChange = (type: GstRegType) => {
    setFormData(prev => ({
      ...prev,
      gstProfile: {
        ...prev.gstProfile!,
        regType: type,
        filingFreq: type === 'Composition' ? 'Quarterly' : prev.gstProfile?.filingFreq || 'Monthly'
      }
    }));
  };

  const handleConstitutionChange = (val: ConstitutionType) => {
    setFormData(prev => {
      const nextGst = { ...prev.gstProfile!, constitution: val };
      if (val === 'Proprietorship' && nextGst.pan && nextGst.stakeholders.length > 0) {
        nextGst.stakeholders[0] = { ...nextGst.stakeholders[0], pan: nextGst.pan };
      }
      return { ...prev, gstProfile: nextGst };
    });
  };

  const updateStakeholder = (id: string, field: keyof Stakeholder, val: string) => {
    setFormData(prev => {
      const updatedStakeholders = prev.gstProfile!.stakeholders.map(s => 
        s.id === id ? { ...s, [field]: val } : s
      );
      return { ...prev, gstProfile: { ...prev.gstProfile!, stakeholders: updatedStakeholders } };
    });
  };

  const addStakeholder = () => {
    setFormData(prev => ({
      ...prev,
      gstProfile: { ...prev.gstProfile!, stakeholders: [...prev.gstProfile!.stakeholders, defaultStakeholder()] }
    }));
  };

  const removeStakeholder = (id: string) => {
    setFormData(prev => {
      if (prev.gstProfile!.stakeholders.length <= 1) return prev;
      return { ...prev, gstProfile: { ...prev.gstProfile!, stakeholders: prev.gstProfile!.stakeholders.filter(s => s.id !== id) } };
    });
  };

  const handleSave = async () => {
    setError(null);
    if (!formData.tradeName) return setError("Trade Name is mandatory.");
    if (!formData.gstProfile?.gstin) return setError("GSTIN identifier required.");

    setIsSaving(true);
    try {
      const saved = await api.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message || "Failed to archive profile.");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[400] flex items-center justify-center bg-slate-900/70 backdrop-blur-md p-4 animate-in fade-in duration-300">
      <div className="w-full max-w-5xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden border border-slate-200">

        <header className="px-10 py-6 border-b border-slate-100 flex items-center justify-between shrink-0">
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase leading-none">{initialData ? 'Update Profile' : 'New GST Enrollment'}</h2>
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mt-1.5">Authorized Compliance Record</p>
          </div>
          <button onClick={onClose} className="p-2.5 bg-slate-50 hover:bg-slate-100 rounded-xl transition-all">
            <svg className="h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto no-scrollbar p-10 space-y-10">
          {error && (
            <div className="p-4 bg-rose-50 border border-rose-100 rounded-xl text-[10px] font-black uppercase text-rose-600 text-center animate-in shake">
              {error}
            </div>
          )}

          <section className="space-y-6">
             <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 flex items-center gap-3">Basic Info <div className="h-px flex-1 bg-slate-100" /></h4>
             <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black uppercase text-slate-400">Trade Name</label>
                   <input className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-black uppercase outline-none focus:border-indigo-600 transition-all text-xs" value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value.toUpperCase()})} placeholder="Business Name" />
                </div>
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black uppercase text-slate-400">Constitution</label>
                   <select className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl font-bold text-xs outline-none cursor-pointer" value={formData.gstProfile?.constitution} onChange={e => handleConstitutionChange(e.target.value as ConstitutionType)}>
                      <option value="Proprietorship">Proprietorship</option>
                      <option value="Partnership">Partnership</option>
                      <option value="Company">Private/Public Ltd</option>
                      <option value="HUF">HUF</option>
                   </select>
                </div>
                <div className="space-y-1.5 col-span-2">
                   <label className="text-[9px] font-black uppercase text-slate-400">Legal Name (PAN)</label>
