                </div>
             </div>
          </section>

          <section className="space-y-6">
             <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 flex items-center gap-3">GST Portal Vault <div className="h-px flex-1 bg-slate-100" /></h4>
